# Inspect residual structure after a flexible additive reference.
rng=np.random.default_rng(2026)
n=100000
X=np.zeros((n,11));X[:,0]=rng.uniform(-4.2,3,n);X[:,1:10]=rng.integers(0,2,(n,9));X[:,10]=rng.uniform(0,10,n)
Y=predict(X).ravel()
def design(X):
 a=X[:,0]/4.2;l=(X[:,10]-5)/5
 return np.column_stack((np.ones(len(X)),X[:,1:10],a,a**2,a**3,a**4,a**5,l,l**2,l**3,l**4,l**5,l**6))
A=design(X);coef=np.linalg.lstsq(A,Y,rcond=None)[0];R=Y-A@coef
print("flexible main effect rms",np.sqrt(np.mean(R**2)))
# Largest conditional-mean residuals over clinical severity/treatment and age bands.
for w in [0,1]:
 for s in [0,1]:
  for lo,hi in [(-4.2,-2),(-2,0),(0,1),(1,3)]:
   mask=(X[:,2]==w)&(X[:,7]==s)&(X[:,0]>=lo)&(X[:,0]<hi)
   print("wfns",w,"surgery",s,"age",lo,hi,"mean residual",round(np.mean(R[mask]),3))
print("Socioeconomic, severity and treatment residuals")
for u in [0,1]:
 for f in [0,1]:
  for w in [0,1]:
   for s in [0,1]:
    mask=(X[:,8]==u)&(X[:,9]==f)&(X[:,2]==w)&(X[:,7]==s)
    print(u,f,w,s,round(np.mean(R[mask]),3))

